        LinearLayout search=a.row();EditText term=input(query,"混合搜索已启用书源；留空浏览热门");search.addView(term,new LinearLayout.LayoutParams(0,-2,1));a.rowButton(search,"搜索",()->{String q=term.getText().toString().trim();if(!q.equals(query))invalidateSearch();query=q;page=1;cachedResults.clear();nextSources.clear();search();});p.addView(search);
        note=a.label("搜索所有已启用来源；可到书源管理选择参与搜索的来源。",14,a.muted);p.addView(note);ScrollView scroll=new ScrollView(a);resultList=a.column();scroll.addView(resultList);p.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=a.row();previous=a.button("上一页",()->{if(page>1){page--;search();}});next=a.button("下一页",()->{page++;search();});nav.addView(previous);nav.addView(next);p.addView(nav);previous.setEnabled(page>1);next.setEnabled(nextSources.containsKey(page)&&!nextSources.get(page).isEmpty());renderResults();
