    void search(){
        if(!query.equals(resultQuery)){cachedResults.clear();nextSources.clear();page=1;resultQuery=query;}
        cancelSearch();final int token=serial,currentPage=page;final String q=query;if(cachedResults.containsKey(page)){results=cachedResults.get(page);renderResults();note.setText("第 "+page+" 页 · "+results.length()+" 部作品");previous.setEnabled(page>1);next.setEnabled(!nextSources.getOrDefault(page,Collections.emptySet()).isEmpty());return;}
        List<JSONObject> enabled=new ArrayList<>();Set<String> allowed=page>1?nextSources.getOrDefault(page-1,Collections.emptySet()):null;for(int i=0;i<online.sources().length();i++){JSONObject source=online.sources().optJSONObject(i);if(source.optBoolean("enabled",true)&&(allowed==null||allowed.contains(source.optString("id"))))try{enabled.add(new JSONObject(source.toString()));}catch(Exception ignored){}}
        results=new JSONArray();renderResults();previous.setEnabled(false);next.setEnabled(false);if(enabled.isEmpty()){note.setText("请先添加或启用书源");previous.setEnabled(page>1);return;}note.setText("正在混合搜索 "+enabled.size()+" 个书源…");final Map<String,Online.Result> completed=new HashMap<>();final Map<String,String> failed=new LinkedHashMap<>();
        for(JSONObject source:enabled)searchJobs.add(searches.submit(()->{Online.Result value=null;String error=null;try{Online.searching.set(true);value=Online.search(source,q,currentPage);}catch(Exception e){error=friendlyError(e);}finally{Online.searching.remove();}final Online.Result response=value;final String failure=error;a.handler.post(()->{if(a.dead||token!=serial||a.screen!=SCREEN)return;String sid=source.optString("id");if(response!=null)completed.put(sid,response);else failed.put(sid,source.optString("name")+"："+failure);JSONArray merged=new JSONArray();Set<String> more=new HashSet<>(),seen=new HashSet<>();try{for(JSONObject cfg:enabled){String id=cfg.optString("id");Online.Result r=completed.get(id);if(r==null)continue;if(r.more)more.add(id);for(int i=0;i<r.books.length();i++){JSONObject b=r.books.getJSONObject(i);if(seen.add(id+"/"+b.getString("id")))merged.put(b.put("source_id",id).put("source_name",cfg.optString("name")));}}}catch(Exception e){a.error("搜索结果无效",e);}results=merged;renderResults();int done=completed.size()+failed.size();note.setText("第 "+currentPage+" 页 · "+merged.length()+" 部作品 · 已返回 "+done+" / "+enabled.size()+" 个来源"+(failed.isEmpty()?"":"\n暂不可用："+android.text.TextUtils.join("；",failed.values())));if(done==enabled.size()){cachedResults.put(currentPage,merged);nextSources.put(currentPage,more);previous.setEnabled(currentPage>1);next.setEnabled(!more.isEmpty());}});}));
    }
    void renderResults(){if(resultList==null)return;resultList.removeAllViews();for(int i=0;i<results.length();i++){JSONObject b=results.optJSONObject(i);LinearLayout card=a.column();card.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));card.setBackground(a.rounded(a.panel,16));card.addView(a.label(b.optString("title"),19,a.text));card.addView(a.label(b.optString("source_name")+" · 点击查看章节并加入书库",13,a.accent));card.setOnClickListener(v->{if(!adding)add(b);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,a.dp(10));resultList.addView(card,lp);}}
    void add(JSONObject book){
        if(adding)return;adding=true;note.setText("正在加载章节目录…");a.imports.execute(()->{try{JSONObject source=online.source(book.getString("source_id"));JSONArray chapters=online.chapters(source,book.getString("id"));a.handler.post(()->{adding=false;if(a.dead)return;try{JSONObject entry=online.add(source,book,chapters);a.showDetail(entry);a.imports.execute(()->{a.generateCover(entry);a.handler.post(()->{if(!a.dead&&a.screen==MainActivity.DETAIL&&a.detail==entry){a.thumbs.evictAll();a.showDetail(entry);}});});}catch(Exception e){a.error("无法加入书库",e);}});}catch(Exception e){a.handler.post(()->{adding=false;if(!a.dead)a.error("无法加入书库",e);});}});
    }
    void readingSettings(){
        LinearLayout form=a.column();form.setPadding(a.dp(20),a.dp(12),a.dp(20),a.dp(12));Spinner quality=new Spinner(a);String[] keys={"smooth","low","original"};quality.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"流畅（默认 · 自适应压缩）","低（节省内存）","原（原图 · 不压缩）"}));quality.setSelection(Math.max(0,Arrays.asList(keys).indexOf(a.store.settings().optString("onlineQuality","smooth"))));form.addView(quality);CheckBox preload=new CheckBox(a);preload.setText("后台预加载相邻页面（仅保留在内存）");preload.setChecked(a.store.settings().optBoolean("onlinePreload",true));form.addView(preload);form.addView(a.label("重新进入章节会复用本次运行已加载的页面。关闭程序后释放；主动下载目录不变。只有支持省流图片的来源可减少网络传输，其他来源收到图片后再压缩。",13,a.muted));
        new AlertDialog.Builder(a).setTitle("在线画质与预加载").setView(form).setPositiveButton("应用",(d,w)->{try{boolean changed=!a.store.settings().optString("onlineQuality","smooth").equals(keys[quality.getSelectedItemPosition()]);a.store.settings().put("onlineQuality",keys[quality.getSelectedItemPosition()]).put("onlinePreload",preload.isChecked());a.clearNearby();a.saveQuiet();if(changed&&a.engine instanceof Online.Engine){JSONObject owner=a.owner;int index=owner.optInt("currentVolume",0);a.openBook(owner,index);}else a.warmNeighbours();}catch(Exception e){a.error("设置失败",e);}}).setNegativeButton("取消",null).show();
    }
    void sources(){
        List<String> names=new ArrayList<>();names.add("＋ 添加书源");names.add("导入书源 JSON 文件");names.add("从链接导入书源包");for(int i=0;i<online.sources().length();i++){JSONObject s=online.sources().optJSONObject(i);names.add((s.optBoolean("enabled",true)?"● ":"○ ")+s.optString("name")+" · "+s.optString("type"));}
        new AlertDialog.Builder(a).setTitle("书源管理").setItems(names.toArray(new String[0]),(d,index)->{if(index==0)edit(null);else if(index==1){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);a.startActivityForResult(i,SOURCE_FILE);}else if(index==2)importUrl();else sourceActions(online.sources().optJSONObject(index-3));}).setNegativeButton("关闭",null).show();
    }
